use aes_gcm_siv::{
    aead::{Aead, KeyInit, OsRng, Payload},
    Aes256GcmSiv, Nonce,
};
use rand::RngCore;

const NONCE_LEN: usize = 12;

#[derive(Debug)]
pub enum CryptoError {
    SealFailed,
    OpenFailed,
    MalformedBlob,
}

fn encode_aad(tenant_id: &str, record_id: &str) -> Vec<u8> {
    let mut aad = Vec::with_capacity(8 + tenant_id.len() + record_id.len());
    aad.extend_from_slice(&(tenant_id.len() as u32).to_be_bytes());
    aad.extend_from_slice(tenant_id.as_bytes());
    aad.extend_from_slice(&(record_id.len() as u32).to_be_bytes());
    aad.extend_from_slice(record_id.as_bytes());
    aad
}

pub fn seal_secret(
    key: &[u8; 32],
    tenant_id: &str,
    record_id: &str,
    plaintext: &[u8],
) -> Result<Vec<u8>, CryptoError> {
    let cipher = Aes256GcmSiv::new(key.into());
    let mut nonce_bytes = [0u8; NONCE_LEN];
    OsRng.fill_bytes(&mut nonce_bytes);
    let aad = encode_aad(tenant_id, record_id);

    let ciphertext = cipher
        .encrypt(
            Nonce::from_slice(&nonce_bytes),
            Payload { msg: plaintext, aad: &aad },
        )
        .map_err(|_| CryptoError::SealFailed)?;

    let mut out = Vec::with_capacity(NONCE_LEN + ciphertext.len());
    out.extend_from_slice(&nonce_bytes);
    out.extend_from_slice(&ciphertext);
    Ok(out)
}

pub fn open_secret(
    key: &[u8; 32],
    tenant_id: &str,
    record_id: &str,
    blob: &[u8],
    on_auth_fail: &dyn Fn(&str),
) -> Result<Vec<u8>, CryptoError> {
    if blob.len() < NONCE_LEN + 16 {
        on_auth_fail(tenant_id);
        return Err(CryptoError::MalformedBlob);
    }
    let (nonce_bytes, ciphertext) = blob.split_at(NONCE_LEN);
    let cipher = Aes256GcmSiv::new(key.into());
    let aad = encode_aad(tenant_id, record_id);

    cipher
        .decrypt(
            Nonce::from_slice(nonce_bytes),
            Payload { msg: ciphertext, aad: &aad },
        )
        .map_err(|_| {
            on_auth_fail(tenant_id);
            CryptoError::OpenFailed
        })
}
