import { DocumentNode, GraphQLError, Kind, visit } from "graphql";

const MAX_DEPTH = 7;
const MAX_ALIASES = 15;
const STRIP_PREFIXES = ["x-internal-", "x-subgraph-", "x-tenant-"];

export function sanitizeSubgraphHeaders(
  incoming: Record<string, string | undefined>,
  verifiedUserId: string,
  verifiedTenantId: string,
  onSpoofAttempt: (headerName: string) => void,
): Record<string, string> {
  const clean: Record<string, string> = {};
  for (const [rawKey, value] of Object.entries(incoming)) {
    if (value === undefined) continue;
    const key = rawKey.toLowerCase();
    if (STRIP_PREFIXES.some((p) => key.startsWith(p))) {
      onSpoofAttempt(key);
      continue;
    }
    if (key === "content-type" || key === "x-request-id" || key === "traceparent") {
      clean[key] = value;
    }
  }
  clean["x-subgraph-user-id"] = verifiedUserId;
  clean["x-subgraph-tenant-id"] = verifiedTenantId;
  return clean;
}

export function enforceAstBounds(doc: DocumentNode, onReject: (reason: string) => void): void {
  let aliasCount = 0;
  let currentDepth = 0;
  let maxSeenDepth = 0;

  visit(doc, {
    Field: {
      enter(node) {
        if (node.name.value.startsWith("__")) {
          onReject("introspection_blocked");
          throw new GraphQLError("Schema introspection is disabled");
        }
        if (node.alias) {
          aliasCount += 1;
          if (aliasCount > MAX_ALIASES) {
            onReject("alias_cap_exceeded");
            throw new GraphQLError("Query alias budget exceeded");
          }
        }
        currentDepth += 1;
        if (currentDepth > maxSeenDepth) maxSeenDepth = currentDepth;
        if (currentDepth > MAX_DEPTH) {
          onReject("depth_cap_exceeded");
          throw new GraphQLError("Query nesting depth exceeded");
        }
      },
      leave() {
        currentDepth -= 1;
      },
    },
  });
}
