package oidcfed

import (
	"errors"
	"log/slog"
)

type GitHubOIDCClaims struct {
	Issuer            string `json:"iss"`
	Audience          string `json:"aud"`
	Subject           string `json:"sub"`
	Repository        string `json:"repository"`
	RepositoryOwnerID string `json:"repository_owner_id"`
	JobWorkflowRef    string `json:"job_workflow_ref"`
	RefProtected      string `json:"ref_protected"`
}

type TrustPolicy struct {
	ExpectedAudience  string
	ExpectedOwnerID   string
	AllowedRepo       string
	ExpectedSubject   string
	AllowedWorkflowPrefix string
}

func VerifyWorkloadClaims(c GitHubOIDCClaims, p TrustPolicy, log *slog.Logger) error {
	if c.Issuer != "https://token.actions.githubusercontent.com" || c.Audience != p.ExpectedAudience {
		log.Warn("oidc_exchange_denied", "reason", "iss_or_aud_mismatch", "sub", c.Subject)
		return errors.New("invalid issuer or audience")
	}
	if c.RepositoryOwnerID != p.ExpectedOwnerID || c.Repository != p.AllowedRepo {
		log.Warn("oidc_exchange_denied", "reason", "untrusted_repo", "repo", c.Repository, "owner_id", c.RepositoryOwnerID)
		return errors.New("untrusted repository identity")
	}
	if c.Subject != p.ExpectedSubject || c.RefProtected != "true" {
		log.Warn("oidc_exchange_denied", "reason", "subject_or_protection_mismatch", "sub", c.Subject)
		return errors.New("subject or branch protection policy failed")
	}
	if len(c.JobWorkflowRef) < len(p.AllowedWorkflowPrefix) ||
		c.JobWorkflowRef[:len(p.AllowedWorkflowPrefix)] != p.AllowedWorkflowPrefix {
		log.Warn("oidc_exchange_denied", "reason", "unapproved_workflow", "workflow_ref", c.JobWorkflowRef)
		return errors.New("unapproved workflow reference")
	}
	log.Info("oidc_exchange_granted", "repo", c.Repository, "sub", c.Subject)
	return nil
}
