```go
package customdomain

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"log/slog"
	"net"
	"strings"
	"time"
)

type Resolver interface {
	LookupCNAME(ctx context.Context, host string) (string, error)
	LookupTXT(ctx context.Context, name string) ([]string, error)
}

func ExpectedOwnershipToken(secret []byte, tenantID, hostname string) string {
	mac := hmac.New(sha256.New, secret)
	mac.Write([]byte(tenantID + "|" + strings.ToLower(hostname)))
	return "acme-verify=" + hex.EncodeToString(mac.Sum(nil))
}

func VerifyVanityDomain(
	ctx context.Context,
	res Resolver,
	secret []byte,
	tenantID, hostname, expectedEdgeTarget string,
	log *slog.Logger,
) error {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	host := strings.TrimSuffix(strings.ToLower(strings.TrimSpace(hostname)), ".")
	if host == "" || net.ParseIP(host) != nil {
		return errors.New("invalid vanity hostname")
	}

	cname, err := res.LookupCNAME(ctx, host)
	if err != nil || strings.TrimSuffix(strings.ToLower(cname), ".") != expectedEdgeTarget {
		log.Warn("domain_verify_failed", "tenant_id", tenantID, "host", host, "reason", "cname_mismatch")
		return errors.New("CNAME does not match edge target")
	}

	txtRecords, err := res.LookupTXT(ctx, "_acme-ownership."+host)
	if err != nil {
		log.Warn("domain_verify_failed", "tenant_id", tenantID, "host", host, "reason", "txt_lookup_error")
		return errors.New("missing TXT ownership record")
	}

	expectedTXT := ExpectedOwnershipToken(secret, tenantID, host)
	for _, rec := range txtRecords {
		if hmac.Equal([]byte(strings.TrimSpace(rec)), []byte(expectedTXT)) {
			log.Info("domain_verified", "tenant_id", tenantID, "host", host)
			return nil
		}
	}

	log.Warn("domain_verify_failed", "tenant_id", tenantID, "host", host, "reason", "txt_token_mismatch")
	return errors.New("domain ownership TXT token mismatch")
}
```

