import logging
import re
from pathlib import Path
from typing import List
import yaml

log = logging.getLogger("cicd.workflow_gate")

PINNED_ACTION_RE = re.compile(r"^[A-Za-z0-9_.-]+/[A-Za-z0-9_./-]+@[0-9a-f]{40}$")


def audit_workflow_file(workflow_path: Path) -> List[str]:
    doc = yaml.safe_load(workflow_path.read_text(encoding="utf-8"))
    if not isinstance(doc, dict):
        return [f"{workflow_path.name}: root YAML is not a mapping"]

    findings: List[str] = []
    top_perms = doc.get("permissions")
    if top_perms == "write-all" or top_perms is None:
        findings.append(f"{workflow_path.name}: top-level permissions must be explicit and never write-all")

    triggers = doc.get("on") or doc.get(True) or {}
    has_prt = isinstance(triggers, dict) and "pull_request_target" in triggers

    jobs = doc.get("jobs", {})
    if not isinstance(jobs, dict):
        return findings

    for job_name, job_cfg in jobs.items():
        if not isinstance(job_cfg, dict):
            continue
        if job_cfg.get("permissions") == "write-all":
            findings.append(f"{workflow_path.name}:{job_name}: job permissions cannot be write-all")
        for step in job_cfg.get("steps", []):
            if not isinstance(step, dict) or "uses" not in step:
                continue
            uses_ref = str(step["uses"]).strip()
            if uses_ref.startswith("./"):
                continue
            if not PINNED_ACTION_RE.match(uses_ref):
                findings.append(f"{workflow_path.name}:{job_name}: unpinned action '{uses_ref}'")
            if has_prt and uses_ref.startswith("actions/checkout@"):
                with_cfg = step.get("with") or {}
                if "ref" in with_cfg:
                    findings.append(f"{workflow_path.name}:{job_name}: checkout ref under pull_request_target")

    if findings:
        log.warning("workflow_gate_failed file=%s violations=%d", workflow_path.name, len(findings))
    return findings
