package envelope

import (
	"context"
	"crypto/rand"
	"errors"

	"golang.org/x/crypto/chacha20poly1305"
)

type KMSWrapper interface {
	GenerateDataKey(ctx context.Context, tenantID string) (plaintextDEK []byte, encryptedDEK []byte, err error)
}

type SealedEnvelope struct {
	WrappedDEK []byte
	Nonce      []byte
	Ciphertext []byte
}

func zeroBytes(buf []byte) {
	for i := range buf {
		buf[i] = 0
	}
}

func SealDocument(
	ctx context.Context,
	kms KMSWrapper,
	tenantID, docID string,
	plaintext []byte,
	onErrorMetric func(string),
) (*SealedEnvelope, error) {
	if tenantID == "" || docID == "" {
		return nil, errors.New("missing tenant or document context")
	}
	plainDEK, wrappedDEK, err := kms.GenerateDataKey(ctx, tenantID)
	if err != nil {
		onErrorMetric("kms_generate_dek_failed")
		return nil, err
	}
	defer zeroBytes(plainDEK)

	aead, err := chacha20poly1305.NewX(plainDEK)
	if err != nil {
		onErrorMetric("aead_init_failed")
		return nil, err
	}

	nonce := make([]byte, chacha20poly1305.NonceSizeX)
	if _, err := rand.Read(nonce); err != nil {
		return nil, err
	}

	aad := []byte(tenantID + "|" + docID)
	ct := aead.Seal(nil, nonce, plaintext, aad)
	return &SealedEnvelope{
		WrappedDEK: wrappedDEK,
		Nonce:      nonce,
		Ciphertext: ct,
	}, nil
}
