package ratelimit

import (
	"context"
	"sync"
	"time"

	"golang.org/x/time/rate"
)

type DistributedCounter interface {
	AllowRemote(ctx context.Context, tenantID string) (bool, error)
}

type ResilientTenantLimiter struct {
	remote        DistributedCounter
	remoteTimeout time.Duration
	localRate     rate.Limit
	localBurst    int
	mu            sync.Mutex
	buckets       map[string]*rate.Limiter
	onMetric      func(name, tenantID string)
}

func NewResilientTenantLimiter(
	remote DistributedCounter,
	fallbackRPS float64,
	fallbackBurst int,
	onMetric func(name, tenantID string),
) *ResilientTenantLimiter {
	return &ResilientTenantLimiter{
		remote:        remote,
		remoteTimeout: 35 * time.Millisecond,
		localRate:     rate.Limit(fallbackRPS),
		localBurst:    fallbackBurst,
		buckets:       make(map[string]*rate.Limiter),
		onMetric:      onMetric,
	}
}

func (l *ResilientTenantLimiter) allowLocal(tenantID string) bool {
	l.mu.Lock()
	lim, ok := l.buckets[tenantID]
	if !ok {
		lim = rate.NewLimiter(l.localRate, l.localBurst)
		l.buckets[tenantID] = lim
	}
	l.mu.Unlock()
	return lim.Allow()
}

func (l *ResilientTenantLimiter) Allow(parent context.Context, tenantID string) bool {
	ctx, cancel := context.WithTimeout(parent, l.remoteTimeout)
	defer cancel()

	allowed, err := l.remote.AllowRemote(ctx, tenantID)
	if err == nil {
		if !allowed {
			l.onMetric("ratelimit_rejected_remote", tenantID)
		}
		return allowed
	}

	l.onMetric("ratelimit_fallback_active", tenantID)
	localOK := l.allowLocal(tenantID)
	if !localOK {
		l.onMetric("ratelimit_rejected_local_fallback", tenantID)
	}
	return localOK
}
