import { KeyObject, verify } from "node:crypto";

export interface JwtClaims {
  iss: string;
  aud: string;
  exp: number;
  sub: string;
}

export function verifyPinnedEs256Jwt(
  token: string,
  trustedKeysByKid: ReadonlyMap<string, KeyObject>,
  expectedIssuer: string,
  expectedAudience: string,
  nowSec: number,
  onReject: (reason: string) => void,
): JwtClaims {
  const parts = token.split(".");
  if (parts.length !== 3) {
    onReject("malformed_compact_jws");
    throw new Error("Invalid JWT structure");
  }
  const [hdrB64, payloadB64, sigB64] = parts;
  const header = JSON.parse(Buffer.from(hdrB64, "base64url").toString("utf8")) as Record<string, unknown>;

  if (header.alg !== "ES256" || "jku" in header || "x5u" in header || "jwk" in header) {
    onReject("forbidden_header_alg_or_remote_key");
    throw new Error("Disallowed JWS header parameters");
  }

  const kid = typeof header.kid === "string" ? header.kid : "";
  const pubKey = trustedKeysByKid.get(kid);
  if (!pubKey || pubKey.asymmetricKeyType !== "ec") {
    onReject("unknown_or_non_ec_kid");
    throw new Error("Unknown signing key identifier");
  }

  const signingInput = Buffer.from(`${hdrB64}.${payloadB64}`, "ascii");
  const signature = Buffer.from(sigB64, "base64url");
  const ok = verify("sha256", signingInput, { key: pubKey, dsaEncoding: "ieee-p1363" }, signature);
  if (!ok) {
    onReject("signature_verification_failed");
    throw new Error("Invalid ES256 signature");
  }

  const claims = JSON.parse(Buffer.from(payloadB64, "base64url").toString("utf8")) as JwtClaims;
  if (claims.iss !== expectedIssuer || claims.aud !== expectedAudience || nowSec >= claims.exp) {
    onReject("claims_validation_failed");
    throw new Error("JWT claims failed validation");
  }
  return claims;
}
