```rust
use ed25519_dalek::{Signature, Signer, SigningKey, Verifier, VerifyingKey};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

const DOMAIN_TAG: &[u8] = b"healthtech.rx.v1\x00";

#[derive(Debug, Serialize, Deserialize)]
pub struct PrescriptionEnvelope {
    pub kid: String,
    pub fields: BTreeMap<String, String>,
    pub signature_hex: String,
}

fn canonical_signing_bytes(kid: &str, fields: &BTreeMap<String, String>) -> Result<Vec<u8>, serde_json::Error> {
    let canonical_json = serde_json::to_vec(fields)?;
    let mut buf = Vec::with_capacity(DOMAIN_TAG.len() + kid.len() + 4 + canonical_json.len());
    buf.extend_from_slice(DOMAIN_TAG);
    buf.extend_from_slice(&(kid.len() as u32).to_be_bytes());
    buf.extend_from_slice(kid.as_bytes());
    buf.extend_from_slice(&canonical_json);
    Ok(buf)
}

pub fn sign_prescription(
    kid: &str,
    signing_key: &SigningKey,
    fields: BTreeMap<String, String>,
) -> Result<PrescriptionEnvelope, serde_json::Error> {
    let msg = canonical_signing_bytes(kid, &fields)?;
    let sig: Signature = signing_key.sign(&msg);
    Ok(PrescriptionEnvelope {
        kid: kid.to_string(),
        fields,
        signature_hex: hex::encode(sig.to_bytes()),
    })
}

pub fn verify_prescription(
    env: &PrescriptionEnvelope,
    trusted_keys: &BTreeMap<String, VerifyingKey>,
) -> Result<(), &'static str> {
    let vk = trusted_keys.get(&env.kid).ok_or("untrusted_kid")?;
    let raw_sig = hex::decode(&env.signature_hex).map_err(|_| "malformed_hex")?;
    let sig = Signature::from_slice(&raw_sig).map_err(|_| "invalid_sig_len")?;
    let msg = canonical_signing_bytes(&env.kid, &env.fields).map_err(|_| "canonicalize_err")?;
    vk.verify(&msg, &sig).map_err(|_| "signature_mismatch")
}
