package tenantcache

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"time"
)

type RedisBackend interface {
	Get(ctx context.Context, key string) ([]byte, error)
	Set(ctx context.Context, key string, val []byte, ttl time.Duration) error
}

type CachedReport struct {
	TenantID string `json:"tenant_id"`
	CSVBytes []byte `json:"csv_bytes"`
}

type ScopedCache struct {
	store   RedisBackend
	hmacKey []byte
}

func NewScopedCache(store RedisBackend, hmacKey []byte) *ScopedCache {
	return &ScopedCache{store: store, hmacKey: hmacKey}
}

func (c *ScopedCache) buildKey(tenantID, filterJSON string) (string, error) {
	if tenantID == "" {
		return "", errors.New("empty_tenant_id")
	}
	mac := hmac.New(sha256.New, c.hmacKey)
	mac.Write([]byte(tenantID + "|" + filterJSON))
	return "tenant:" + tenantID + ":report:" + hex.EncodeToString(mac.Sum(nil)), nil
}

func (c *ScopedCache) GetReport(ctx context.Context, tenantID, filterJSON string) ([]byte, error) {
	key, err := c.buildKey(tenantID, filterJSON)
	if err != nil {
		return nil, err
	}
	raw, err := c.store.Get(ctx, key)
	if err != nil {
		return nil, err
	}
	var env CachedReport
	if err := json.Unmarshal(raw, &env); err != nil {
		return nil, err
