import hashlib
import hmac
import json
from dataclasses import dataclass
from typing import Optional, Protocol


class AtomicKV(Protocol):
    def set_if_absent(self, key: str, value: str, ttl_sec: int) -> bool: ...
    def get(self, key: str) -> Optional[str]: ...


@dataclass(frozen=True)
class IdempotencyCheckResult:
    is_replay: bool
    cached_response_json: Optional[str]


def verify_or_claim_idempotency(
    kv: AtomicKV,
    tenant_id: str,
    route: str,
    idem_key: str,
    body_obj: dict,
) -> IdempotencyCheckResult:
    if not tenant_id or not idem_key or len(idem_key) > 128:
        raise ValueError("invalid_tenant_or_idempotency_key")

    canonical_body = json.dumps(body_obj, sort_keys=True, separators=(",", ":")).encode("utf-8")
    body_sha256 = hashlib.sha256(canonical_body).hexdigest()
    scoped_key = f"idem:{tenant_id}:{route}:{idem_key}"

    pending_record = json.dumps({"state": "in_flight", "body_sha256": body_sha256, "resp": None})
    if kv.set_if_absent(scoped_key, pending_record, ttl_sec=86400):
        return IdempotencyCheckResult(is_replay=False, cached_response_json=None)

    existing_raw = kv.get(scoped_key)
    if existing_raw is None:
        raise RuntimeError("transient_idempotency_state_missing")

    record = json.loads(existing_raw)
    if not hmac.compare_digest(record["body_sha256"], body_sha256):
        raise PermissionError("idempotency_payload_mismatch")
    if record["state"] == "in_flight":
        raise RuntimeError("concurrent_request_in_flight")

    return IdempotencyCheckResult(is_replay=True, cached_response_json=record["resp"])
