use rand::RngCore;
use zeroize::Zeroizing;

pub struct SealedVaultRecord {
    pub wrapped_dek: Vec<u8>,
    pub nonce: [u8; 12],
    pub ciphertext: Vec<u8>,
}

pub trait KmsEnvelope {
    fn generate_data_key(&self, tenant_id: &str) -> Result<(Zeroizing<[u8; 32]>, Vec<u8>), &'static str>;
    fn decrypt_data_key(&self, tenant_id: &str, wrapped: &[u8]) -> Result<Zeroizing<[u8; 32]>, &'static str>;
