import { createHmac, timingSafeEqual } from "node:crypto";

const MAX_WEBHOOK_BYTES = 512 * 1024;

export interface InstallationSecretStore {
  getSecretByInstallationId(installId: string): Promise<string | null>;
}

export async function verifyGitOpsWebhook(
  rawBody: Buffer,
  headers: Record<string, string | undefined>,
  secrets: InstallationSecretStore,
): Promise<Record<string, unknown>> {
  if (rawBody.byteLength === 0 || rawBody.byteLength > MAX_WEBHOOK_BYTES) {
    throw new Error("webhook_payload_out_of_bounds");
  }

  const installId = headers["x-github-hook-installation-target-id"] ?? "";
  if (!/^[0-9]{1,20}$/.test(installId)) {
    throw new Error("invalid_installation_header");
  }

  const sigHeader = headers["x-hub-signature-256"] ?? "";
  if (!/^sha256=[0-9a-f]{64}$/.test(sigHeader)) {
    throw new Error("malformed_signature_header");
  }

  const secret = await secrets.getSecretByInstallationId(installId);
  if (!secret) {
    throw new Error("unknown_installation");
  }

  const expectedHex = createHmac("sha256", secret).update(rawBody).digest("hex");
  const expectedBuf = Buffer.from(`sha256=${expectedHex}`, "utf8");
  const providedBuf = Buffer.from(sigHeader, "utf8");

  if (expectedBuf.length !== providedBuf.length || !timingSafeEqual(expectedBuf, providedBuf)) {
    throw new Error("webhook_signature_mismatch");
  }

  return JSON.parse(rawBody.toString("utf8")) as Record<string, unknown>;
}
