const maxAcceptBodyBytes = 4096

type AcceptTradeDTO struct {
	BuyerWalletID    string `json:"buyer_wallet_id"`
	ExpectedPriceGold int64  `json:"expected_price_gold"`
}

type TradeService interface {
	AcceptEscrowTrade(tradeID, buyerID, walletID string, expectedPrice int64) error
}

func HandleAcceptTrade(svc TradeService, authBuyer func(*http.Request) (string, bool)) http.HandlerFunc {
