			return
		}
		if err := dec.Decode(&struct{}{}); err != io.EOF {
			http.Error(w, "trailing_json_tokens", http.StatusBadRequest)
			return
		}
		if dto.BuyerWalletID == "" || dto.ExpectedPriceGold <= 0 {
			http.Error(w, "invalid_field_bounds", http.StatusUnprocessableEntity)
			return
		}

		if err := svc.AcceptEscrowTrade(r.PathValue("tradeId"), buyerID, dto.BuyerWalletID, dto.ExpectedPriceGold); err != nil {
