use jsonwebtoken::{decode, decode_header, Algorithm, DecodingKey, Validation};
use serde::Deserialize;
use std::collections::HashMap;

#[derive(Debug, Deserialize)]
pub struct EdgeWorkerClaims {
    pub sub: String,
    pub iss: String,
    pub aud: String,
    pub exp: usize,
    pub tenant_id: String,
}

pub struct PinnedJwtVerifier {
    keys: HashMap<String, DecodingKey>,
    expected_issuer: String,
    expected_audience: String,
}

impl PinnedJwtVerifier {
    pub fn verify_token(&self, raw_jwt: &str) -> Result<EdgeWorkerClaims, &'static str> {
        let header = decode_header(raw_jwt).map_err(|_| "malformed_jwt_header")?;
