package llmproxy

import (
	"bytes"
	"encoding/json"
	"io"
	"net/http"
	"sync"
)

const (
	maxPromptBodyBytes = 64 * 1024
	maxCompletionToks  = 2048
	maxTenantInFlight  = 4
)

type completionReq struct {
	Model     string            `json:"model"`
	Messages  []json.RawMessage `json:"messages"`
	MaxTokens int               `json:"max_tokens"`
	N         int               `json:"n,omitempty"`
}

type TenantGate struct {
	mu   sync.Mutex
	sems map[string]chan struct{}
}

func NewTenantGate() *TenantGate {
	return &TenantGate{sems: make(map[string]chan struct{})}
}

func (g *TenantGate) acquire(tenantID string) (func(), bool) {
	g.mu.Lock()
	ch, ok := g.sems[tenantID]
	if !ok {
		ch = make(chan struct{}, maxTenantInFlight)
		g.sems[tenantID] = ch
	}
	g.mu.Unlock()
	select {
	case ch <- struct{}{}:
		return func() { <-ch }, true
	default:
		return nil, false
	}
}

func GuardInferenceIngress(gate *TenantGate, resolveTenant func(*http.Request) string, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		tenantID := resolveTenant(r)
		release, ok := gate.acquire(tenantID)
		if !ok {
			http.Error(w, "tenant_gpu_concurrency_exceeded", http.StatusTooManyRequests)
			return
		}
		defer release()

		r.Body = http.MaxBytesReader(w, r.Body, maxPromptBodyBytes)
		raw, err := io.ReadAll(r.Body)
		if err != nil {
			http.Error(w, "prompt_payload_too_large", http.StatusRequestEntityTooLarge)
			return
		}
		var req completionReq
		if err := json.Unmarshal(raw, &req); err != nil || req.MaxTokens <= 0 || req.MaxTokens > maxCompletionToks || req.N > 1 || len(req.Messages) == 0 {
			http.Error(w, "violates_inference_token_bounds", http.StatusUnprocessableEntity)
			return
		}
		r.Body = io.NopCloser(bytes.NewReader(raw))
		next.ServeHTTP(w, r)
	})
}
