	txAEAD cipher.AEAD
	rxAEAD cipher.AEAD
	txSeq  uint64
}

func deriveAEAD(ikm, salt []byte, info string) (cipher.AEAD, error) {
	kdf := hkdf.New(sha256.New, ikm, salt, []byte(info))
	key := make([]byte, 32)
	if _, err := io.ReadFull(kdf, key); err != nil {
		return nil, err
	}
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	return cipher.NewGCM(block)
}

func NewServerSessionCodec(sharedIKM, matchSalt []byte) (*DirectionalCodec, error) {
	tx, err := deriveAEAD(sharedIKM, matchSalt, "game.udp.v1.s2c")
	if err != nil {
		return nil, err
	}
	rx, err := deriveAEAD(sharedIKM, matchSalt, "game.udp.v1.c2s")
	if err != nil {
		return nil, err
	}
	return &DirectionalCodec{txAEAD: tx, rxAEAD: rx}, nil
}

func (c *DirectionalCodec) SealServerFrame(matchID uint32, plaintext []byte) []byte {
	c.txSeq++
	nonce := make([]byte, 12)
	binary.BigEndian.PutUint32(nonce[0:4], matchID)
	binary.BigEndian.PutUint64(nonce[4:12], c.txSeq)
	return c.txAEAD.Seal(nonce, nonce, plaintext, nonce)
}
