const MAX_RESPONSE_BYTES = 256 * 1024;

export async function safeAgentHttpGet(
  rawUrl: string,
  tenantAllowedHosts: ReadonlySet<string>,
  timeoutMs = 5000,
): Promise<string> {
  let parsed: URL;
  try {
    parsed = new URL(rawUrl);
  } catch {
    throw new Error("invalid_tool_url");
  }

