import (
	"io"
	"net/http"
)

const maxEmblemBytes = 512 * 1024

var allowedRasterTypes = map[string]bool{
	"image/png":  true,
	"image/webp": true,
}

func ServeVerifiedRasterEmblem(loadBlob func(id string) ([]byte, error)) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		data, err := loadBlob(r.PathValue("id"))
		if err != nil || len(data) == 0 || len(data) > maxEmblemBytes {
			http.Error(w, "not_found", http.StatusNotFound)
			return
		}

		sniffLen := len(data)
		if sniffLen > 512 {
			sniffLen = 512
		}
		detected := http.DetectContentType(data[:sniffLen])
		if !allowedRasterTypes[detected] {
			http.Error(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
			return
		}

		w.Header().Set("Content-Type", detected)
		w.Header().Set("X-Content-Type-Options", "nosniff")
		w.Header().Set("Content-Security-Policy", "sandbox; default-src 'none'; img-src 'self'")
		w.Header().Set("Cache-Control", "public, max-age=3600, immutable")
		w.WriteHeader(http.StatusOK)
		_, _ = io.Writer.Write(w, data)
	}
}
