		jwt.WithIssuer(expectedIssuer),
		jwt.WithAudience(expectedAudience),
		jwt.WithLeeway(15*time.Second),
		jwt.WithExpirationRequired(),
	)
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			r.Header.Del("X-ZT-User-Email")
			rawAssertion := r.Header.Get("X-ZT-Jwt-Assertion")
			if rawAssertion == "" {
				log.Warn("zt_missing_assertion", "remote_addr", r.RemoteAddr, "path", r.URL.Path)
				http.Error(w, "unauthorized", http.StatusUnauthorized)
				return
			}
			claims := jwt.MapClaims{}
			tok, err := parser.ParseWithClaims(rawAssertion, claims, func(t *jwt.Token) (any, error) {
				if _, ok := t.Method.(*jwt.SigningMethodECDSA); !ok {
					return nil, errors.New("unexpected alg")
				}
				return pubKey, nil
			})
			if err != nil || !tok.Valid {
				log.Warn("zt_invalid_assertion", "remote_addr", r.RemoteAddr, "err", err)
				http.Error(w, "forbidden", http.StatusForbidden)
				return
			}
			sub, _ := claims["sub"].(string)
			email, _ := claims["email"].(string)
			if sub == "" || email == "" {
				http.Error(w, "forbidden", http.StatusForbidden)
				return
			}
			ctx := context.WithValue(r.Context(), ctxKey{}, VerifiedPrincipal{Subject: sub, Email: email})
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}
