use ring::digest::{digest, SHA256};
use serde::Deserialize;
use subtle::ConstantTimeEq;

const FLAG_USER_PRESENT: u8 = 0x01;
const FLAG_USER_VERIFIED: u8 = 0x04;
const FLAG_ATTESTED_CRED_DATA: u8 = 0x40;

#[derive(Debug, PartialEq, Eq)]
pub enum PasskeyVerifyError {
    MalformedClientData,
    WrongCeremonyType,
    ChallengeMismatch,
    UntrustedOrigin,
    ShortAuthData,
    RpIdHashMismatch,
    UserVerificationMissing,
}

#[derive(Deserialize)]
struct ClientDataJson {
    #[serde(rename = "type")]
    ceremony_type: String,
    challenge: String,
    origin: String,
}

pub fn verify_registration_core(
    client_data_bytes: &[u8],
    auth_data: &[u8],
    expected_challenge_b64url: &str,
    expected_rp_id: &str,
    allowed_origins: &[&str],
) -> Result<(), PasskeyVerifyError> {
    let cdata: ClientDataJson = serde_json::from_slice(client_data_bytes)
        .map_err(|_| PasskeyVerifyError::MalformedClientData)?;

    if cdata.ceremony_type != "webauthn.create" {
        return Err(PasskeyVerifyError::WrongCeremonyType);
    }
    if cdata.challenge.as_bytes().ct_eq(expected_challenge_b64url.as_bytes()).unwrap_u8() != 1 {
        return Err(PasskeyVerifyError::ChallengeMismatch);
    }
    if !allowed_origins.iter().any(|o| *o == cdata.origin) {
        return Err(PasskeyVerifyError::UntrustedOrigin);
    }
    if auth_data.len() < 37 {
        return Err(PasskeyVerifyError::ShortAuthData);
    }
    let expected_rp_hash = digest(&SHA256, expected_rp_id.as_bytes());
    if auth_data[0..32].ct_eq(expected_rp_hash.as_ref()).unwrap_u8() != 1 {
        return Err(PasskeyVerifyError::RpIdHashMismatch);
    }
    let flags = auth_data[32];
    let required = FLAG_USER_PRESENT | FLAG_USER_VERIFIED | FLAG_ATTESTED_CRED_DATA;
    if (flags & required) != required {
        return Err(PasskeyVerifyError::UserVerificationMissing);
    }
    Ok(())
}
