CREATE TABLE accounts (
    account_id UUID PRIMARY KEY,
    home_region TEXT NOT NULL CHECK (home_region IN ('us-east-1', 'eu-central-1')),
    cached_balance_cents BIGINT NOT NULL DEFAULT 0 CHECK (cached_balance_cents >= 0)
);

CREATE TABLE ledger_entries (
    entry_id UUID PRIMARY KEY,
    account_id UUID NOT NULL REFERENCES accounts (account_id),
    origin_region TEXT NOT NULL,
    idempotency_key TEXT NOT NULL,
    delta_cents BIGINT NOT NULL CHECK (delta_cents <> 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (account_id, idempotency_key)
);

CREATE TABLE ledger_audit_rejections (
    rejection_id BIGSERIAL PRIMARY KEY,
    account_id UUID NOT NULL,
    attempted_region TEXT NOT NULL,
    reason TEXT NOT NULL,
    observed_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION post_fenced_debit(
    p_account_id UUID,
    p_local_region TEXT,
    p_idempotency_key TEXT,
    p_debit_cents BIGINT
) RETURNS BIGINT
LANGUAGE plpgsql AS $$
DECLARE
    v_home TEXT;
    v_bal  BIGINT;
BEGIN
    IF p_debit_cents <= 0 THEN
        RAISE EXCEPTION 'debit_must_be_positive';
    END IF;

    SELECT home_region, cached_balance_cents
      INTO v_home, v_bal
      FROM accounts
     WHERE account_id = p_account_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'unknown_account';
    END IF;

    IF v_home <> p_local_region THEN
        INSERT INTO ledger_audit_rejections (account_id, attempted_region, reason)
        VALUES (p_account_id, p_local_region, 'wrong_home_region');
        RAISE EXCEPTION 'region_fence_violation: route write to %', v_home;
    END IF;

    IF EXISTS (
        SELECT 1 FROM ledger_entries
         WHERE account_id = p_account_id AND idempotency_key = p_idempotency_key
    ) THEN
        RETURN v_bal;
    END IF;

    IF v_bal < p_debit_cents THEN
        RAISE EXCEPTION 'insufficient_funds';
    END IF;

    INSERT INTO ledger_entries (entry_id, account_id, origin_region, idempotency_key, delta_cents)
    VALUES (gen_random_uuid(), p_account_id, p_local_region, p_idempotency_key, -p_debit_cents);

    UPDATE accounts
       SET cached_balance_cents = cached_balance_cents - p_debit_cents
     WHERE account_id = p_account_id
    RETURNING cached_balance_cents INTO v_bal;

    RETURN v_bal;
END;
$$;
