import { createHmac, hkdfSync, timingSafeEqual } from "node:crypto";

const MAX_CLOCK_SKEW_SEC = 300;

export interface ScanWebhookEnvelope {
  tenantId: string;
  repository: string;
  manifestDigest: string;
  verdict: "clean" | "quarantined";
}

function deriveTenantWebhookKey(masterSecret: Buffer, tenantId: string): Buffer {
  if (masterSecret.length < 32) {
    throw new Error("Master secret requires >= 32 bytes");
  }
  const raw = hkdfSync(
    "sha256",
    masterSecret,
    Buffer.alloc(32, 0),
    Buffer.from(`oci-scan-webhook:v1:${tenantId}`, "utf8"),
    32,
  );
  return Buffer.from(raw);
}

export function signTenantScanEvent(
  masterSecret: Buffer,
  envelope: ScanWebhookEnvelope,
  timestampSec: number,
): { body: string; signatureHeader: string; timestampHeader: string } {
  const body = JSON.stringify(envelope);
  const key = deriveTenantWebhookKey(masterSecret, envelope.tenantId);
  const canonical = `${timestampSec}.${envelope.tenantId}.${envelope.manifestDigest}.${body}`;
  const mac = createHmac("sha256", key).update(canonical, "utf8").digest("hex");
  return {
    body,
    signatureHeader: `v1=${mac}`,
    timestampHeader: String(timestampSec),
  };
}

export function verifyTenantScanEvent(
  masterSecret: Buffer,
  expectedTenantId: string,
  rawBody: string,
  timestampHeader: string,
  signatureHeader: string,
  nowSec: number = Math.floor(Date.now() / 1000),
): ScanWebhookEnvelope {
  const ts = Number.parseInt(timestampHeader, 10);
  if (!Number.isSafeInteger(ts) || Math.abs(nowSec - ts) > MAX_CLOCK_SKEW_SEC) {
    throw new Error("expired_or_invalid_timestamp");
  }
  const parsed = JSON.parse(rawBody) as ScanWebhookEnvelope;
  if (parsed.tenantId !== expectedTenantId || !/^sha256:[a-f0-9]{64}$/.test(parsed.manifestDigest)) {
    throw new Error("tenant_or_digest_mismatch");
  }
  const key = deriveTenantWebhookKey(masterSecret, expectedTenantId);
  const canonical = `${ts}.${expectedTenantId}.${parsed.manifestDigest}.${rawBody}`;
  const expectedSig = Buffer.from(`v1=${createHmac("sha256", key).update(canonical, "utf8").digest("hex")}`, "ascii");
  const providedSig = Buffer.from(signatureHeader, "utf8");
  if (expectedSig.length !== providedSig.length || !timingSafeEqual(expectedSig, providedSig)) {
    throw new Error("signature_mismatch");
  }
  return parsed;
}
