package ocitoken

import (
	"errors"
	"log/slog"
	"regexp"
	"strings"
)

var repoNameRe = regexp.MustCompile(`^[a-z0-9]+(?:[._/-][a-z0-9]+)*$`)

type AccessEntry struct {
	Type    string   `json:"type"`
	Name    string   `json:"name"`
	Actions []string `json:"actions"`
}

type Authorizer interface {
	CanAccessRepo(subject, repo, action string) bool
}

func ValidateAndAuthorizeScopes(
	subject string,
	rawScopes []string,
	authz Authorizer,
	log *slog.Logger,
) ([]AccessEntry, error) {
	if len(rawScopes) > 10 {
		return nil, errors.New("too_many_scopes")
	}
	granted := make([]AccessEntry, 0, len(rawScopes))
	for _, raw := range rawScopes {
		parts := strings.Split(raw, ":")
		if len(parts) != 3 || parts[0] != "repository" || !repoNameRe.MatchString(parts[1]) {
			return nil, errors.New("malformed_scope")
		}
		repo := parts[1]
		actions := strings.Split(parts[2], ",")
		cleanActions := make([]string, 0, len(actions))
		for _, act := range actions {
			if act != "pull" && act != "push" {
				return nil, errors.New("unsupported_action")
			}
			if !authz.CanAccessRepo(subject, repo, act) {
				log.Warn("oci_scope_denied", "subject", subject, "repo", repo, "action", act)
				return nil, errors.New("unauthorized_scope")
			}
			cleanActions = append(cleanActions, act)
		}
		granted = append(granted, AccessEntry{Type: "repository", Name: repo, Actions: cleanActions})
	}
	return granted, nil
}
