const FLAG_UP = 0x01;
const FLAG_UV = 0x04;
const FLAG_BE = 0x08;
const FLAG_BS = 0x10;
const FLAG_AT = 0x40;

export interface HardwarePasskeyPolicy {
  allowedAaguids: ReadonlySet<string>;
  onReject: (reason: string, meta: Record<string, unknown>) => void;
}

function formatUuid(bytes: Uint8Array): string {
  const hex = Buffer.from(bytes).toString("hex");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20, 32)}`;
}

export function enforceHardwareBoundPasskey(
  authData: Uint8Array,
  userId: string,
  policy: HardwarePasskeyPolicy,
): { aaguid: string; signCount: number } {
  if (authData.byteLength < 55) {
    throw new Error("short_authenticator_data");
  }
  const flags = authData[32];
  if ((flags & (FLAG_UP | FLAG_UV | FLAG_AT)) !== (FLAG_UP | FLAG_UV | FLAG_AT)) {
    policy.onReject("missing_uv_or_attestation", { userId, flags });
    throw new Error("uv_and_attested_data_required");
  }
  if ((flags & (FLAG_BE | FLAG_BS)) !== 0) {
    policy.onReject("synced_passkey_disallowed", { userId, flags });
    throw new Error("hardware_bound_passkey_required");
  }
  const view = new DataView(authData.buffer, authData.byteOffset, authData.byteLength);
  const signCount = view.getUint32(33, false);
  const aaguid = formatUuid(authData.subarray(37, 53));
  if (!policy.allowedAaguids.has(aaguid)) {
    policy.onReject("unapproved_aaguid", { userId, aaguid });
    throw new Error("unapproved_hardware_key_model");
  }
  return { aaguid, signCount };
}
