```rust
use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
use chacha20poly1305::{
    aead::{Aead, KeyInit, OsRng, Payload},
    XChaCha20Poly1305, XNonce,
};
use rand::RngCore;

const XNONCE_LEN: usize = 24;
const TAG_LEN: usize = 16;

#[derive(Debug)]
pub enum CookieCryptoError {
    InvalidEncoding,
    MalformedLength,
    SealFailure,
    OpenFailure,
}

fn build_aad(host: &str, cookie_name: &str) -> Vec<u8> {
    let mut aad = Vec::with_capacity(8 + host.len() + cookie_name.len());
    aad.extend_from_slice(&(host.len() as u32).to_be_bytes());
    aad.extend_from_slice(host.as_bytes());
    aad.extend_from_slice(&(cookie_name.len() as u32).to_be_bytes());
    aad.extend_from_slice(cookie_name.as_bytes());
    aad
}

pub fn seal_session_cookie(
    key_bytes: &[u8; 32],
    host: &str,
    cookie_name: &str,
    plaintext: &[u8],
) -> Result<String, CookieCryptoError> {
    let cipher = XChaCha20Poly1305::new(key_bytes.into());
    let mut nonce_bytes = [0u8; XNONCE_LEN];
    OsRng.fill_bytes(&mut nonce_bytes);
    let aad = build_aad(host, cookie_name);
    let ct = cipher
        .encrypt(
            XNonce::from_slice(&nonce_bytes),
            Payload { msg: plaintext, aad: &aad },
        )
        .map_err(|_| CookieCryptoError::SealFailure)?;
    let mut out = Vec::with_capacity(XNONCE_LEN + ct.len());
    out.extend_from_slice(&nonce_bytes);
    out.extend_from_slice(&ct);
    Ok(URL_SAFE_NO_PAD.encode(out))
}

pub fn open_session_cookie(
    key_bytes: &[u8; 32],
    host: &str,
    cookie_name: &str,
    encoded: &str,
) -> Result<Vec<u8>, CookieCryptoError> {
    let raw = URL_SAFE_NO_PAD
        .decode(encoded)
        .map_err(|_| CookieCryptoError::InvalidEncoding)?;
    if raw.len() < XNONCE_LEN + TAG_LEN {
        return Err(CookieCryptoError::MalformedLength);
    }
    let (nonce_bytes, ct) = raw.split_at(XNONCE_LEN);
    let aad = build_aad(host, cookie_name);
    let cipher = XChaCha20Poly1305::new(key_bytes.into());
    cipher
        .decrypt(XNonce::from_slice(nonce_bytes), Payload { msg: ct, aad: &aad })
        .map_err(|_| CookieCryptoError::OpenFailure)
}
