import logging
import re
from typing import Callable, Awaitable

log = logging.getLogger("zt.saas_edge")

TENANT_HOST_RE = re.compile(r"^([a-z0-9][a-z0-9-]{1,61})\.access\.acme\.cloud$")


class ZeroTrustTenantHostMiddleware:
    def __init__(self, app: Callable[..., Awaitable[None]]) -> None:
        self.app = app

    async def __call__(self, scope: dict, receive: Callable, send: Callable) -> None:
        if scope["type"] != "http":
            await self.app(scope, receive, send)
            return

        headers = {k.lower(): v.decode("latin1") for k, v in scope.get("headers", [])}
        raw_host = headers.get("host", "").split(":", 1)[0].lower()
        match = TENANT_HOST_RE.match(raw_host)
        if not match:
            log.warning("zt_invalid_host_header host=%r client=%s", raw_host, scope.get("client"))
            await send({
                "type": "http.response.start",
                "status": 400,
                "headers": [(b"content-type", b"application/json"), (b"cache-control", b"no-store")],
            })
            await send({"type": "http.response.body", "body": b'{"error":"invalid_tenant_host"}'})
            return

        scope["state"] = {**scope.get("state", {}), "tenant_slug": match.group(1)}

        async def send_with_cache_guards(message: dict) -> None:
            if message["type"] == "http.response.start":
                filtered = [
                    (k, v) for k, v in message.get("headers", [])
                    if k.lower() not in {b"cache-control", b"vary", b"pragma"}
                ]
                filtered.extend([
                    (b"cache-control", b"private, no-store, max-age=0"),
                    (b"vary", b"Host, Authorization, Cookie"),
                ])
                message = {**message, "headers": filtered}
            await send(message)

        await self.app(scope, receive, send_with_cache_guards)
