package ragauthz

import (
	"context"
	"log/slog"

	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/credentials"
	"google.golang.org/grpc/peer"
	"google.golang.org/grpc/status"
)

type TenantScopedRequest interface {
	GetTenantId() string
}

func RequireSpiffeVectorWriter(
	allowedSpiffeIDs map[string]bool,
	log *slog.Logger,
) grpc.UnaryServerInterceptor {
	return func(
		ctx context.Context,
		req any,
		info *grpc.UnaryServerInfo,
		handler grpc.UnaryHandler,
	) (any, error) {
		p, ok := peer.FromContext(ctx)
		if !ok || p.AuthInfo == nil {
			return nil, status.Error(codes.Unauthenticated, "missing_peer_auth")
		}
		tlsInfo, ok := p.AuthInfo.(credentials.TLSInfo)
		if !ok || len(tlsInfo.State.VerifiedChains) == 0 || len(tlsInfo.State.PeerCertificates) == 0 {
			return nil, status.Error(codes.Unauthenticated, "mtls_verification_required")
		}
		leaf := tlsInfo.State.PeerCertificates[0]
		if len(leaf.URIs) != 1 {
			return nil, status.Error(codes.PermissionDenied, "ambiguous_spiffe_san")
		}
		spiffeID := leaf.URIs[0].String()
		if !allowedSpiffeIDs[spiffeID] {
			log.Warn("rag_unauthorized_spiffe", "spiffe_id", spiffeID, "method", info.FullMethod)
			return nil, status.Error(codes.PermissionDenied, "spiffe_not_authorized_for_vector_sync")
		}
		if scoped, ok := req.(TenantScopedRequest); ok && scoped.GetTenantId() == "" {
			return nil, status.Error(codes.InvalidArgument, "missing_tenant_id")
		}
		return handler(ctx, req)
	}
}
