use serde::Deserialize;

const MAX_INDEX_BYTES: usize = 4 * 1024 * 1024;
const MAX_DESCRIPTORS: usize = 128;
const MAX_ANNOTATIONS: usize = 32;

#[derive(Debug, PartialEq, Eq)]
pub enum ManifestValidationError {
    PayloadTooLarge,
    InvalidJson,
    UnsupportedSchemaVersion,
    TooManyDescriptors,
    InvalidDigest,
    InvalidSize,
    TooManyAnnotations,
}

#[derive(Deserialize)]
pub struct OciDescriptor {
    #[serde(rename = "mediaType")]
    pub media_type: String,
    pub digest: String,
    pub size: i64,
}

#[derive(Deserialize)]
pub struct OciImageIndex {
    #[serde(rename = "schemaVersion")]
    pub schema_version: u32,
    pub manifests: Vec<OciDescriptor>,
    #[serde(default)]
    pub annotations: std::collections::BTreeMap<String, String>,
}

fn is_valid_sha256_digest(d: &str) -> bool {
    match d.strip_prefix("sha256:") {
        Some(hex) => hex.len() == 64 && hex.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()),
        None => false,
    }
}

pub fn parse_verified_image_index(raw: &[u8]) -> Result<OciImageIndex, ManifestValidationError> {
    if raw.len() > MAX_INDEX_BYTES {
        return Err(ManifestValidationError::PayloadTooLarge);
    }
    let idx: OciImageIndex = serde_json::from_slice(raw)
        .map_err(|_| ManifestValidationError::InvalidJson)?;
    if idx.schema_version != 2 {
        return Err(ManifestValidationError::UnsupportedSchemaVersion);
    }
    if idx.manifests.is_empty() || idx.manifests.len() > MAX_DESCRIPTORS {
        return Err(ManifestValidationError::TooManyDescriptors);
    }
    if idx.annotations.len() > MAX_ANNOTATIONS {
        return Err(ManifestValidationError::TooManyAnnotations);
    }
    for desc in &idx.manifests {
        if !is_valid_sha256_digest(&desc.digest) {
            return Err(ManifestValidationError::InvalidDigest);
        }
        if desc.size <= 0 {
            return Err(ManifestValidationError::InvalidSize);
        }
    }
    Ok(idx)
}
