import { createHash, randomBytes } from "node:crypto";

const RECOVERY_TTL_MS = 15 * 60 * 1000;

export interface RecoveryStore {
  insertHashedToken(params: {
    tokenHashHex: string;
    tenantId: string;
    userId: string;
    expiresAt: Date;
  }): Promise<void>;
  consumeValidTokenAtomically(params: {
    tokenHashHex: string;
    tenantId: string;
    userId: string;
    now: Date;
  }): Promise<boolean>;
  audit(event: string, meta: Record<string, unknown>): void;
}

function sha256Hex(rawToken: string): string {
  return createHash("sha256").update(rawToken, "utf8").digest("hex");
}

export async function issuePasskeyRecoveryToken(
  store: RecoveryStore,
  tenantId: string,
  userId: string,
): Promise<string> {
  const rawToken = randomBytes(32).toString("base64url");
  const tokenHashHex = sha256Hex(rawToken);
  const expiresAt = new Date(Date.now() + RECOVERY_TTL_MS);
  await store.insertHashedToken({ tokenHashHex, tenantId, userId, expiresAt });
  return rawToken;
}

export async function redeemPasskeyRecoveryToken(
  store: RecoveryStore,
  tenantId: string,
  userId: string,
  presentedToken: string,
): Promise<void> {
  if (presentedToken.length < 40 || presentedToken.length > 64) {
    store.audit("passkey_recovery_malformed", { tenantId, userId });
    throw new Error("invalid_recovery_token");
  }
  const tokenHashHex = sha256Hex(presentedToken);
  const claimed = await store.consumeValidTokenAtomically({
    tokenHashHex,
    tenantId,
    userId,
    now: new Date(),
  });
  if (!claimed) {
    store.audit("passkey_recovery_rejected", { tenantId, userId });
    throw new Error("invalid_or_expired_recovery_token");
  }
}
